# Fala, Transcrição e IA — lote L15, segunda leva
TG="y"
Q = []
TAILS=[" Essa seria a posição predominante na literatura técnica da área.",
 " Trata-se de entendimento consolidado na literatura técnica contemporânea.",
 " Tal conclusão decorreria, segundo esse entendimento, das características da tecnologia descrita.",
 " Essa seria a leitura mais aceita entre os estudiosos do tema."]
SHORT=[" Isso é consenso na área."," Essa é a regra geral."," Trata-se de prática corrente."," Esse é o entendimento usual."]
def tail(E,C,i):
    gap=len(C)-len(E)
    if len(E) < 0.97*len(C) and gap > 60: return E+TAILS[i%len(TAILS)]
    if len(E) < 0.92*len(C) and gap > 14: return E+SHORT[i%len(SHORT)]
    return E
FD={"tipo":"doutrina","ref":"literatura técnica de ASR e IA; LGPD; Lei 9.610/1998","versao":"conhecimento do autor","conferida":"conhecimento"}
FJ={"tipo":"jurisprudencia","ref":"jurisprudência","versao":"conhecimento do autor","conferida":"conhecimento"}
def P(ponto, arts, padC, padE, dif, C, E, com, terro, tag, jur=False, lei=False):
    ex = {}
    if lei: ex["fonte"]={"tipo":"lei","ref":"Lei 13.709/2018; Lei 9.610/1998","versao":"vigente","conferida":"conhecimento"}
    elif jur: ex["fonte"]=FJ; ex["risco"]=["jurisprudencia_conhecimento"]
    else: ex["fonte"]=FD; ex["risco"]=["doutrina_conhecimento"]
    E = tail(E, C, len(Q))
    padC = padE if padC == 'conceito_correto' else padC
    Q.append((ponto, arts, "C", padC, dif, C, com, "", tag, ex))
    Q.append((ponto, arts, "E", padE, dif, E, com, terro, tag, ex))
_n={}
def G(i,padE,dif,C,E,com,terro,lei=False,jur=False):
    _n[i]=_n.get(i,0)+1
    P(f"F{i:02d}",[str(i+25)],"conceito_correto",padE,dif,C,E,com,terro,f"{TG}{i:02d}{_n[i]}",lei=lei,jur=jur)
# ---- 11 fidelidade (átomo 36)
G(11,"confusao_instituto",3,"Na transcrição limpa (verbatim inteligente), suprimem-se marcas de oralidade sem relevância, preservando o sentido, ao passo que na literal registram-se hesitações, repetições e falsos começos.","Na transcrição limpa (verbatim inteligente), registram-se hesitações, repetições e falsos começos, ao passo que na literal suprimem-se as marcas de oralidade.","Tipos de transcrição.","inverte literal e limpa")
G(11,"excecao_omitida",3,"Quando o orador comete erro de fato, como troca de data ou número, o transcritor não o corrige silenciosamente, podendo manter a forma original com indicação adequada, como (sic), conforme o manual do órgão.","Quando o orador comete erro de fato, como troca de data ou número, o transcritor deve corrigi-lo silenciosamente, sem qualquer indicação.","Erro de fato do orador.","autoriza correção silenciosa")
G(11,"excecao_omitida",3,"O registro de eventos que não são fala, como palmas e risos, deve ser feito de forma neutra, sem adjetivação e sem interpretação.","O registro de eventos que não são fala, como palmas e risos, deve ser feito com adjetivação e interpretação, para melhor transmitir o clima da sessão.","Eventos não verbais.","autoriza adjetivação")
G(11,"caso_concreto",3,"Um orador diz 'nós vamos, né, votar a matéria'. Na transcrição de fidelidade ao conteúdo adotada em registros parlamentares, a expressão 'né' pode ser suprimida sem alterar o sentido.","Um orador diz 'nós vamos, né, votar a matéria'. Na transcrição de fidelidade ao conteúdo adotada em registros parlamentares, a supressão de 'né' é vedada, porque qualquer alteração configura adulteração do discurso.","Supressão de vícios.","veda supressão de marcas sem relevância")
G(11,"excecao_omitida",3,"Citações textuais feitas pelo orador devem ser conferidas com a fonte, e expressões em língua estrangeira costumam ser destacadas.","Citações textuais feitas pelo orador dispensam conferência com a fonte, e expressões em língua estrangeira devem ser traduzidas sem indicação.","Citações.","dispensa conferência")
